  public static Gv markdown(Gv cfg = default(Gv)) {
    Gv out_ = Gv.S("# Parametry modelu – zdroj a nejistota\n\nTypy: MEASURED (změřeno), MANUFACTURER (doklad / údaj provozovatele), LITERATURE, ESTIMATED (odhad), CALIBRATED, UNKNOWN.\nPřepsat hodnotu jde souborem `kalibrace.json` ve složce dat aplikace (stejná jako uložená várka), např. `{\"rvpUAst\": {\"value\": 7.2, \"source\": \"CALIBRATED\"}}`.\n\n| Parametr | Hodnota | Jednotka | Zdroj | Nejistota | Poznámka / jak změřit |\n|---|---|---|---|---|---|\n");
    Gv keys = META.C("keys");
    keys.C("sort");
    foreach (Gv k in (keys).Iter()) {
      Gv m = META.I(k);
      out_ = (out_ + (Gv.S("| %s | %s | %s | %s | %s | %s |\n") % Gd.Arr(k, Gd.Dyn("str", cfg.C("get", k, Gv.S("?"))), m.I(Gv.I(0L)), m.I(Gv.I(1L)), m.I(Gv.I(2L)), m.I(Gv.I(3L)))));
    }
    out_ = (out_ + Gv.S("\n## Čerpadla a potrubí\n\n| Prvek | Hodnota | Zdroj | Poznámka |\n|---|---|---|---|\n"));
    foreach (Gv k_2 in (PUMPS_META).Iter()) {
      Gv p = PUMPS_META.I(k_2);
      out_ = (out_ + (Gv.S("| %s | %s | %s | %s |\n") % Gd.Arr(k_2, p.I(Gv.I(0L)), p.I(Gv.I(1L)), p.I(Gv.I(2L)))));
    }
    Gv miss = Gd.Arr();
    foreach (Gv k_3 in (cfg).Iter()) {
      if ((Gv.Is(cfg.I(k_3), "float") && !(META.C("has", k_3)).T())) {
        miss.C("append", k_3);
      }
    }
    if ((miss.C("size")).T()) {
      out_ = (out_ + (Gv.S("\nBez popisu (ESTIMATED, doplnit): %s\n") % Gv.S(", ").C("join", Gd.Ctor("PackedStringArray", miss))));
    }
    return out_;
    return Gv.Null;
  }
